36	/** dateDiff('unit', t1, t2, [timezone])
37	  * t1 and t2 can be Date or DateTime
38	  *
39	  * If timezone is specified, it applied to both arguments.
40	  * If not, timezones from datatypes t1 and t2 are used.
41	  * If that timezones are not the same, the result is unspecified.
42	  *
43	  * Timezone matters because days can have different length.
44	  */
45	class FunctionDateDiff : public IFunction
46	{
47	    using ColumnDateTime64 = ColumnDecimal<DateTime64>;
48	public:
49	    static constexpr auto name = "dateDiff";
50	    static FunctionPtr create(ContextPtr) { return std::make_shared<FunctionDateDiff>(); }
51	
52	    String getName() const override
53	    {
54	        return name;
55	    }
56	
57	    bool isVariadic() const override { return true; }
58	    bool isSuitableForShortCircuitArgumentsExecution(const DataTypesWithConstInfo & /*arguments*/) const override { return true; }
59	    size_t getNumberOfArguments() const override { return 0; }
60	
61	    DataTypePtr getReturnTypeImpl(const DataTypes & arguments) const override
62	    {
63	        if (arguments.size() != 3 && arguments.size() != 4)
64	            throw Exception("Number of arguments for function " + getName() + " doesn't match: passed "
65	                + toString(arguments.size()) + ", should be 3 or 4",
66	                ErrorCodes::NUMBER_OF_ARGUMENTS_DOESNT_MATCH);
67	
68	        if (!isString(arguments[0]))
69	            throw Exception("First argument for function " + getName() + " (unit) must be String",
70	                ErrorCodes::ILLEGAL_TYPE_OF_ARGUMENT);
71	
72	        if (!isDate(arguments[1]) && !isDateTime(arguments[1]) && !isDateTime64(arguments[1]))
73	            throw Exception("Second argument for function " + getName() + " must be Date or DateTime",
74	                ErrorCodes::ILLEGAL_TYPE_OF_ARGUMENT);
75	
76	        if (!isDate(arguments[2]) && !isDateTime(arguments[2]) && !isDateTime64(arguments[2]))
77	            throw Exception("Third argument for function " + getName() + " must be Date or DateTime",
78	                ErrorCodes::ILLEGAL_TYPE_OF_ARGUMENT);
79	
80	        if (arguments.size() == 4 && !isString(arguments[3]))
81	            throw Exception("Fourth argument for function " + getName() + " (timezone) must be String",
82	                ErrorCodes::ILLEGAL_TYPE_OF_ARGUMENT);
83	
84	        return std::make_shared<DataTypeInt64>();
85	    }
86	
87	    bool useDefaultImplementationForConstants() const override { return true; }
88	    ColumnNumbers getArgumentsThatAreAlwaysConstant() const override { return {0, 3}; }
89	
90	    ColumnPtr executeImpl(const ColumnsWithTypeAndName & arguments, const DataTypePtr &, size_t input_rows_count) const override
91	    {
92	        const auto * unit_column = checkAndGetColumnConst<ColumnString>(arguments[0].column.get());
93	        if (!unit_column)
94	            throw Exception("First argument for function " + getName() + " must be constant String", ErrorCodes::ILLEGAL_COLUMN);
95	
96	        String unit = Poco::toLower(unit_column->getValue<String>());
97	
98	        const IColumn & x = *arguments[1].column;
99	        const IColumn & y = *arguments[2].column;
100	
101	        size_t rows = input_rows_count;
102	        auto res = ColumnInt64::create(rows);
103	
104	        const auto & timezone_x = extractTimeZoneFromFunctionArguments(arguments, 3, 1);
105	        const auto & timezone_y = extractTimeZoneFromFunctionArguments(arguments, 3, 2);
106	
107	        if (unit == "year" || unit == "yy" || unit == "yyyy")
108	            dispatchForColumns<ToRelativeYearNumImpl>(x, y, timezone_x, timezone_y, res->getData());
109	        else if (unit == "quarter" || unit == "qq" || unit == "q")
110	            dispatchForColumns<ToRelativeQuarterNumImpl>(x, y, timezone_x, timezone_y, res->getData());
111	        else if (unit == "month" || unit == "mm" || unit == "m")
112	            dispatchForColumns<ToRelativeMonthNumImpl>(x, y, timezone_x, timezone_y, res->getData());
113	        else if (unit == "week" || unit == "wk" || unit == "ww")
114	            dispatchForColumns<ToRelativeWeekNumImpl>(x, y, timezone_x, timezone_y, res->getData());
115	        else if (unit == "day" || unit == "dd" || unit == "d")
116	            dispatchForColumns<ToRelativeDayNumImpl>(x, y, timezone_x, timezone_y, res->getData());
117	        else if (unit == "hour" || unit == "hh")
118	            dispatchForColumns<ToRelativeHourNumImpl>(x, y, timezone_x, timezone_y, res->getData());
119	        else if (unit == "minute" || unit == "mi" || unit == "n")
120	            dispatchForColumns<ToRelativeMinuteNumImpl>(x, y, timezone_x, timezone_y, res->getData());
121	        else if (unit == "second" || unit == "ss" || unit == "s")
122	            dispatchForColumns<ToRelativeSecondNumImpl>(x, y, timezone_x, timezone_y, res->getData());
123	        else
124	            throw Exception("Function " + getName() + " does not support '" + unit + "' unit", ErrorCodes::BAD_ARGUMENTS);
125	
126	        return res;
127	    }
