129	private:
130	    template <typename Transform>
131	    void dispatchForColumns(
132	        const IColumn & x, const IColumn & y,
133	        const DateLUTImpl & timezone_x, const DateLUTImpl & timezone_y,
134	        ColumnInt64::Container & result) const
135	    {
136	        if (const auto * x_vec_16 = checkAndGetColumn<ColumnUInt16>(&x))
137	            dispatchForSecondColumn<Transform>(*x_vec_16, y, timezone_x, timezone_y, result);
138	        else if (const auto * x_vec_32 = checkAndGetColumn<ColumnUInt32>(&x))
139	            dispatchForSecondColumn<Transform>(*x_vec_32, y, timezone_x, timezone_y, result);
140	        else if (const auto * x_vec_64 = checkAndGetColumn<ColumnDateTime64>(&x))
141	            dispatchForSecondColumn<Transform>(*x_vec_64, y, timezone_x, timezone_y, result);
142	        else if (const auto * x_const_16 = checkAndGetColumnConst<ColumnUInt16>(&x))
143	            dispatchConstForSecondColumn<Transform>(x_const_16->getValue<UInt16>(), y, timezone_x, timezone_y, result);
144	        else if (const auto * x_const_32 = checkAndGetColumnConst<ColumnUInt32>(&x))
145	            dispatchConstForSecondColumn<Transform>(x_const_32->getValue<UInt32>(), y, timezone_x, timezone_y, result);
146	        else if (const auto * x_const_64 = checkAndGetColumnConst<ColumnDateTime64>(&x))
147	            dispatchConstForSecondColumn<Transform>(x_const_64->getValue<DecimalField<DateTime64>>(), y, timezone_x, timezone_y, result);
148	        else
149	            throw Exception("Illegal column for first argument of function " + getName() + ", must be Date, DateTime or DateTime64", ErrorCodes::ILLEGAL_COLUMN);
150	    }
151	
152	    template <typename Transform, typename LeftColumnType>
153	    void dispatchForSecondColumn(
154	        const LeftColumnType & x, const IColumn & y,
155	        const DateLUTImpl & timezone_x, const DateLUTImpl & timezone_y,
156	        ColumnInt64::Container & result) const
157	    {
158	        if (const auto * y_vec_16 = checkAndGetColumn<ColumnUInt16>(&y))
159	            vectorVector<Transform>(x, *y_vec_16, timezone_x, timezone_y, result);
160	        else if (const auto * y_vec_32 = checkAndGetColumn<ColumnUInt32>(&y))
161	            vectorVector<Transform>(x, *y_vec_32, timezone_x, timezone_y, result);
162	        else if (const auto * y_vec_64 = checkAndGetColumn<ColumnDateTime64>(&y))
163	            vectorVector<Transform>(x, *y_vec_64, timezone_x, timezone_y, result);
164	        else if (const auto * y_const_16 = checkAndGetColumnConst<ColumnUInt16>(&y))
165	            vectorConstant<Transform>(x, y_const_16->getValue<UInt16>(), timezone_x, timezone_y, result);
166	        else if (const auto * y_const_32 = checkAndGetColumnConst<ColumnUInt32>(&y))
167	            vectorConstant<Transform>(x, y_const_32->getValue<UInt32>(), timezone_x, timezone_y, result);
168	        else if (const auto * y_const_64 = checkAndGetColumnConst<ColumnDateTime64>(&y))
169	            vectorConstant<Transform>(x, y_const_64->getValue<DecimalField<DateTime64>>(), timezone_x, timezone_y, result);
170	        else
171	            throw Exception("Illegal column for second argument of function " + getName() + ", must be Date or DateTime", ErrorCodes::ILLEGAL_COLUMN);
172	    }
173	
174	    template <typename Transform, typename T1>
175	    void dispatchConstForSecondColumn(
176	        T1 x, const IColumn & y,
177	        const DateLUTImpl & timezone_x, const DateLUTImpl & timezone_y,
178	        ColumnInt64::Container & result) const
179	    {
180	        if (const auto * y_vec_16 = checkAndGetColumn<ColumnUInt16>(&y))
181	            constantVector<Transform>(x, *y_vec_16, timezone_x, timezone_y, result);
182	        else if (const auto * y_vec_32 = checkAndGetColumn<ColumnUInt32>(&y))
183	            constantVector<Transform>(x, *y_vec_32, timezone_x, timezone_y, result);
184	        else if (const auto * y_vec_64 = checkAndGetColumn<ColumnDateTime64>(&y))
185	            constantVector<Transform>(x, *y_vec_64, timezone_x, timezone_y, result);
186	        else
187	            throw Exception("Illegal column for second argument of function " + getName() + ", must be Date or DateTime", ErrorCodes::ILLEGAL_COLUMN);
188	    }
189	
190	    template <typename Transform, typename LeftColumnType, typename RightColumnType>
191	    void vectorVector(
192	        const LeftColumnType & x, const RightColumnType & y,
193	        const DateLUTImpl & timezone_x, const DateLUTImpl & timezone_y,
194	        ColumnInt64::Container & result) const
195	    {
196	        const auto & x_data = x.getData();
197	        const auto & y_data = y.getData();
198	
199	        const auto transform_x = TransformDateTime64<Transform>(getScale(x));
200	        const auto transform_y = TransformDateTime64<Transform>(getScale(y));
201	        for (size_t i = 0, size = x.size(); i < size; ++i)
202	                result[i] = calculate(transform_x, transform_y, x_data[i], y_data[i], timezone_x, timezone_y);
203	    }
204	
205	    template <typename Transform, typename LeftColumnType, typename T2>
206	    void vectorConstant(
207	        const LeftColumnType & x, T2 y,
208	        const DateLUTImpl & timezone_x, const DateLUTImpl & timezone_y,
209	        ColumnInt64::Container & result) const
210	    {
211	        const auto & x_data = x.getData();
212	        const auto transform_x = TransformDateTime64<Transform>(getScale(x));
213	        const auto transform_y = TransformDateTime64<Transform>(getScale(y));
214	        const auto y_value = stripDecimalFieldValue(y);
215	
216	        for (size_t i = 0, size = x.size(); i < size; ++i)
217	            result[i] = calculate(transform_x, transform_y, x_data[i], y_value, timezone_x, timezone_y);
218	    }
219	
220	    template <typename Transform, typename T1, typename RightColumnType>
221	    void constantVector(
222	        T1 x, const RightColumnType & y,
223	        const DateLUTImpl & timezone_x, const DateLUTImpl & timezone_y,
224	        ColumnInt64::Container & result) const
225	    {
226	        const auto & y_data = y.getData();
227	        const auto transform_x = TransformDateTime64<Transform>(getScale(x));
228	        const auto transform_y = TransformDateTime64<Transform>(getScale(y));
229	        const auto x_value = stripDecimalFieldValue(x);
230	
231	        for (size_t i = 0, size = y.size(); i < size; ++i)
232	            result[i] = calculate(transform_x, transform_y, x_value, y_data[i], timezone_x, timezone_y);
233	    }
234	
235	    template <typename TransformX, typename TransformY, typename T1, typename T2>
236	    Int64 calculate(const TransformX & transform_x, const TransformY & transform_y, T1 x, T2 y, const DateLUTImpl & timezone_x, const DateLUTImpl & timezone_y) const
237	    {
238	        return static_cast<Int64>(transform_y.execute(y, timezone_y))
239	             - static_cast<Int64>(transform_x.execute(x, timezone_x));
240	    }
241	
242	    template <typename T>
243	    static UInt32 getScale(const T & v)
244	    {
245	        if constexpr (std::is_same_v<T, ColumnDateTime64>)
246	            return v.getScale();
247	        else if constexpr (std::is_same_v<T, DecimalField<DateTime64>>)
248	            return v.getScale();
249	
250	        return 0;
251	    }
252	    template <typename T>
253	    static auto stripDecimalFieldValue(T && v)
254	    {
255	        if constexpr (std::is_same_v<std::decay_t<T>, DecimalField<DateTime64>>)
256	            return v.getValue();
257	        else
258	            return v;
259	    }
260	};
261	
262	}
